def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_sequence(n, length=38):
    """Checks if any S(n+i) for i=0 to 37 is divisible by 11."""
    for i in range(length):
        current_n = n + i
        s_val = sum_digits(current_n)
        if s_val % 11 == 0:
            return False, s_val
    return True, None

